import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [dailyData, setDailyData] = useState([]);
  const [recentCustomers, setRecentCustomers] = useState([]);

  useEffect(() => {
    loadDashboard();
  }, []);

  const loadDashboard = async () => {
    try {
      setLoading(true);
      const res = await API.get('/dashboard');
      setStats(res.data.data.stats);
      setDailyData(res.data.data.dailyData || []);
      setRecentCustomers(res.data.data.recentCustomers || []);
    } catch (error) {
      toast.error('Failed to load dashboard data');
      console.error('Dashboard error:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading dashboard...</div>;
  }

  if (!stats) {
    return <div className="loading">No data available</div>;
  }

  const statCards = [
    { label: 'Total Customers', value: stats.totalCustomers, color: '#2a7de1' },
    { label: 'Active', value: stats.active, color: '#28a745' },
    { label: 'Cut Off', value: stats.cutOff, color: '#dc3545' },
    { label: 'Disable', value: stats.disable, color: '#6c757d' },
    { label: 'Paid', value: stats.paid, color: '#28a745' },
    { label: 'Unpaid', value: stats.unpaid, color: '#dc3545' },
    { label: 'Total Revenue', value: `PKR ${stats.totalRevenue.toLocaleString()}`, color: '#2a7de1' },
    { label: 'Total Dues', value: `PKR ${stats.totalDues.toLocaleString()}`, color: '#dc3545' },
    { label: 'Collected', value: `PKR ${stats.collected.toLocaleString()}`, color: '#28a745' },
    { label: 'Pending Collection', value: `PKR ${stats.pendingCollection.toLocaleString()}`, color: '#fd7e14' },
    { label: 'Total Expenses', value: `PKR ${stats.totalExpenses.toLocaleString()}`, color: '#dc3545' },
    { label: 'Net Profit', value: `PKR ${stats.netProfit.toLocaleString()}`, color: stats.netProfit >= 0 ? '#28a745' : '#dc3545' },
  ];

  // Calculate max values for charts
  const maxRevenue = Math.max(...dailyData.map(d => d.revenue), 1);
  const maxCount = Math.max(...dailyData.map(d => d.count), 1);
  
  // Filter out days with no data for cleaner display
  const hasData = dailyData.some(d => d.count > 0 || d.revenue > 0);

  // Get only days that have data
  const chartData = hasData ? dailyData : [];

  return (
    <div>
      <h2 style={{ marginBottom: '20px' }}>Dashboard Overview</h2>

      {/* Stats Grid */}
      <div style={styles.grid}>
        {statCards.map((card, index) => (
          <div key={index} style={styles.card}>
            <div style={styles.cardLabel}>{card.label}</div>
            <div style={{ ...styles.cardValue, color: card.color }}>{card.value}</div>
          </div>
        ))}
      </div>

      {/* Daily Revenue Chart */}
      <div style={styles.chartSection}>
        <h3 style={styles.sectionTitle}>Daily Revenue (by Due Date)</h3>
        {hasData ? (
          <div style={styles.chartContainer}>
            {chartData.map((item) => (
              <div key={item.day} style={styles.chartBarWrapper}>
                <div style={styles.chartBar}>
                  <div
                    style={{
                      ...styles.barRevenue,
                      height: `${Math.max((item.revenue / maxRevenue) * 140, 4)}px`,
                    }}
                  />
                </div>
                <div style={styles.chartLabel}>{item.day}</div>
                <div style={styles.chartValue}>{item.revenue > 0 ? `${(item.revenue/1000).toFixed(1)}k` : ''}</div>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ textAlign: 'center', color: '#6b7f99', padding: '20px' }}>No revenue data available yet</p>
        )}
        <div style={styles.chartLegend}>
          <span style={{ color: '#6b7f99', fontSize: '12px' }}>📊 Revenue by Day of Month (1-31)</span>
        </div>
      </div>

      {/* Daily Customers Chart */}
      <div style={styles.chartSection}>
        <h3 style={styles.sectionTitle}>Customers by Due Date</h3>
        {hasData ? (
          <div style={styles.chartContainer}>
            {chartData.map((item) => (
              <div key={item.day} style={styles.chartBarWrapper}>
                <div style={styles.chartBar}>
                  <div
                    style={{
                      ...styles.barCustomers,
                      height: `${Math.max((item.count / maxCount) * 140, 4)}px`,
                    }}
                  />
                </div>
                <div style={styles.chartLabel}>{item.day}</div>
                <div style={styles.chartValue}>{item.count > 0 ? item.count : ''}</div>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ textAlign: 'center', color: '#6b7f99', padding: '20px' }}>No customer data available yet</p>
        )}
        <div style={styles.chartLegend}>
          <span style={{ color: '#6b7f99', fontSize: '12px' }}>👥 Customers by Day of Month (1-31)</span>
        </div>
      </div>

      {/* Recent Customers */}
      <div style={styles.recentSection}>
        <h3 style={styles.sectionTitle}>Recent Customers</h3>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Customer ID</th>
              <th>Monthly Fee</th>
              <th>Status</th>
              <th>Payment</th>
            </tr>
          </thead>
          <tbody>
            {recentCustomers.length === 0 ? (
              <tr><td colSpan="5" style={{ textAlign: 'center', padding: '20px', color: '#6b7f99' }}>No customers found</td></tr>
            ) : (
              recentCustomers.map((c) => (
                <tr key={c._id}>
                  <td><strong>{c.name}</strong></td>
                  <td>{c.customerId}</td>
                  <td>PKR {c.monthlyFee.toLocaleString()}</td>
                  <td>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.status === 'Active' ? '#d4edda' : c.status === 'Cut Off' ? '#f8d7da' : '#e2e3e5',
                      color: c.status === 'Active' ? '#155724' : c.status === 'Cut Off' ? '#721c24' : '#383d41',
                    }}>
                      {c.status}
                    </span>
                  </td>
                  <td>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.paymentStatus === 'Paid' ? '#d4edda' : c.paymentStatus === '1 YEAR ADVANCED' ? '#cce5ff' : c.paymentStatus === 'FREE' ? '#e2e3e5' : '#f8d7da',
                      color: c.paymentStatus === 'Paid' ? '#155724' : c.paymentStatus === '1 YEAR ADVANCED' ? '#004085' : c.paymentStatus === 'FREE' ? '#383d41' : '#721c24',
                    }}>
                      {c.paymentStatus}
                    </span>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

